\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	% Grid
	\begin{scope}
		\draw [black!20, step=0.5] (-2,-1) grid (4,5);
	\end{scope}

	\coordinate [label={below:$A$}] (A) at (1,0.5)  {};
	\coordinate (B) at (2.5,2.5)  {};
	\coordinate (C) at (2.5,2.5)  {};
	\coordinate [label={right:$B$}] (D) at (3,3.5)  {};
	\coordinate [label={above left:$H$}] (H) at (1,3.5)  {};

	\draw[|-|, solid, line width=1.2pt, deepskyblue] (-1.5,4.5) -- (-0.5,4.5)
		node[midway, yshift=-10pt]{\small ${10\:\textrm{mm}}$};

	% Vector 1
	\draw[->, line width=1.2pt, black, arrows={-latex}] (A) -- (B)
		node[midway, below right]{$\textbf{\color{black}a}$};

	% Vector 2
	\draw[->, line width=1.2pt, black, arrows={-latex}] (C) -- (D)
		node[midway, below right]{$\mathbf{\color{black}b}$};

	% Resultant
	\draw[->, line width=1.2pt, rustred, arrows={-latex}] (A) -- (D)
		node[sloped, midway, above]{$\mathbf{a}+\mathbf{b}$};

	% Catheti
	\draw[dashed, line width=1.2pt, fadedpink] (A) -- (H);
	\draw[dashed, line width=1.2pt, fadedpink] (D) -- (H);

\end{tikzpicture}
\end{document}
